-- Private isolated data; the entire test is rolled back. No real accounts or PINs.
begin;
do $test$
declare
 owner_id uuid:=gen_random_uuid();admin_id uuid:=gen_random_uuid();staff_id uuid:=gen_random_uuid();org uuid:=gen_random_uuid();a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();
 batch uuid:=gen_random_uuid();receipt uuid:=gen_random_uuid();run_id uuid:=gen_random_uuid();next_run uuid:=gen_random_uuid();doc uuid:=gen_random_uuid();
 product uuid:=gen_random_uuid(); account_id uuid:=gen_random_uuid(); lot_id uuid:=gen_random_uuid();
 r jsonb;input jsonb;saved jsonb;req uuid:=gen_random_uuid();raw_goods jsonb;raw_fields jsonb;raw_members jsonb;pin_count bigint;started timestamptz; reminder uuid; reserved uuid; zone_id uuid:=gen_random_uuid(); state jsonb; before_positions jsonb;
begin
 assert not has_function_privilege('anon','public.get_baihuayuan_receipt_accounts(uuid,date,date,text,uuid)','EXECUTE'),'anonymous read';
 assert not has_function_privilege('anon','public.save_baihuayuan_receipt_review(uuid,uuid,jsonb,uuid)','EXECUTE'),'anonymous write';
 assert not has_table_privilege('authenticated','private.receipt_account_edits','SELECT,INSERT,UPDATE,DELETE'),'direct correction table access';
 insert into auth.users(id,email,email_confirmed_at,created_at,updated_at) select id,id||'@receipt-review.invalid',now(),now(),now() from unnest(array[owner_id,admin_id,staff_id]) id;
 insert into public.profiles(id,display_name) select id,'隔離核對測試' from unnest(array[owner_id,admin_id,staff_id]) id on conflict(id) do nothing;
 insert into public.organizations(id,name,business_type,store_mode) values(org,'核對隔離測試','SINGLE_RESTAURANT','MULTI');
 insert into public.stores(id,organization_id,name,store_code,created_by) values(a,org,'BeApe','RR'||substr(a::text,1,8),owner_id),(b,org,'Gras','RR'||substr(b::text,1,8),owner_id);
 insert into public.organization_members(organization_id,user_id,role,is_owner,can_manage_business) values(org,owner_id,'OWNER',true,true),(org,admin_id,'LOGISTICS',false,false),(org,staff_id,'STAFF',false,false);
 insert into public.staff_identities(organization_id,user_id,display_name,created_by) select org,id,'隔離核對測試',owner_id from unnest(array[owner_id,admin_id,staff_id]) id;
 insert into public.store_memberships(store_id,organization_id,user_id,login_identifier,role,work_role,assigned_by,can_manage_business) values(a,org,owner_id,'rr-owner','OWNER','OWNER',owner_id,true),(a,org,admin_id,'rr-admin','LOGISTICS','LOGISTICS',owner_id,false),(a,org,staff_id,'rr-staff','STAFF','STAFF',owner_id,false),(b,org,owner_id,'rr-owner-b','OWNER','OWNER',owner_id,true);
 perform set_config('request.jwt.claim.sub',owner_id::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',owner_id,'role','authenticated')::text,true);
 insert into public.receipt_upload_batches(id,organization_id,store_id,store_name,work_date,uploaded_by,batch_number,status,group_mode) values(batch,org,a,'BeApe','2026-09-15',owner_id,'RR-ONLY','COMPLETED','SAME_RECEIPT');
 insert into public.receipt_ocr_runs(id,organization_id,batch_id,version,provider,model,prompt_version,status,started_by) values(run_id,org,batch,1,'FIXTURE','rollback-only','fixture-v1','SUCCEEDED',owner_id);
 insert into public.receipt_ocr_fields(organization_id,batch_id,ocr_run_id,row_key,field_name,raw_value,normalized_value,confidence,review_status)
 select org,batch,run_id,'document',key,value,value,1,'TRUSTED' from jsonb_each(jsonb_build_object('supplier_name','核對測試廠商','receipt_date','2026-09-15','document_number','RR-ONLY','subtotal_ex_tax',100,'tax',5,'total_inc_tax',105))
 union all select org,batch,run_id,'line-1',key,value,value,1,'TRUSTED' from jsonb_each(jsonb_build_object('product','測試麵粉','unit','包','quantity',2,'unit_price_ex_tax',50,'subtotal_ex_tax',100));
 insert into public.goods_receipts(id,organization_id,store_id,source_batch_id,receipt_date,document_number,subtotal_ex_tax,tax,total_inc_tax,reviewed_by,reviewed_at) values(receipt,org,a,batch,'2026-09-15','RR-ONLY',100,5,105,owner_id,now());
 insert into public.receipt_documents(id,organization_id,batch_id,storage_path,original_filename,page_order,mime_type,uploaded_by) values(doc,org,batch,org||'/'||batch||'/fixture.png','fixture.png',1,'image/png',owner_id);
 select to_jsonb(g) into raw_goods from public.goods_receipts g where id=receipt;
 select jsonb_agg(to_jsonb(f) order by f.id) into raw_fields from public.receipt_ocr_fields f where batch_id=batch;
 select jsonb_agg(to_jsonb(m) order by m.store_id,m.user_id) into raw_members from public.store_memberships m where organization_id=org;
 select count(*) into pin_count from private.staff_pin_credentials;

 insert into public.products(id,organization_id,name,category,count_unit,base_unit) values(product,org,'測試麵粉','食材','包','包');
 insert into public.count_zones(id,organization_id,store_id,name) values(zone_id,org,a,'回滾測試區');
 insert into public.zone_products(zone_id,product_id,count_unit) values(zone_id,product,'包');
 assert not has_function_privilege('anon','public.baihuayuan_custody_reminders(uuid,text,jsonb,uuid)','EXECUTE'),'anonymous reminder access';
 assert not has_table_privilege('authenticated','private.custody_reminders','SELECT,INSERT,UPDATE,DELETE'),'direct reminder access';
 assert not has_function_privilege('authenticated','private.sync_receipt_reminder(uuid,uuid,text,jsonb,jsonb)','EXECUTE'),'internal helper access';
 input:=jsonb_build_object('product_id',product,'supplier','核對測試廠商','unit','包','kind','supplier','remaining',100,'note','');
 state:=public.baihuayuan_custody_reminders(a,'save',input,req);reminder:=(state#>>'{rows,0,id}')::uuid;
 assert public.baihuayuan_custody_reminders(a,'save',input,req)=state,'create retry';
 state:=public.baihuayuan_custody_reminders(a,'save',input||jsonb_build_object('kind','reserved','remaining',20),gen_random_uuid());
 select id into reserved from private.custody_reminders where store_id=a and kind='reserved';
 perform set_config('request.jwt.claim.sub',staff_id::text,true);
 begin perform public.baihuayuan_custody_reminders(a,'save',input,gen_random_uuid());raise exception 'staff write accepted';exception when insufficient_privilege then null;end;
 begin perform public.baihuayuan_custody_reminders(b);raise exception 'cross store read accepted';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',owner_id::text,true);
 select coalesce(jsonb_agg(to_jsonb(p)),'[]') into before_positions from private.stock_positions p where store_id=a;
 r:=public.get_baihuayuan_receipt_accounts(a,null,null,null,batch)->0;
 input:=jsonb_build_object('source_fingerprint',r->>'source_fingerprint','revision',r->'revision','header',jsonb_build_object('supplier_name',r->>'supplier_name','receipt_date','2026-09-15','document_number','RR-ONLY'),
 'lines',jsonb_build_array((r->'lines'->0)||jsonb_build_object('custody_reminder_id',reminder,'handling','NORMAL','quantity',2,'unit_price',50,'subtotal',100)), 'adjustment',0,'tax',5,'total',105,'note','','checked',false);
 req:=gen_random_uuid();saved:=public.save_baihuayuan_receipt_review(a,batch,input,req);
 assert (select remaining from private.custody_reminders where id=reminder)=98,'100 minus 2';
 assert saved#>>'{account,lines,0,custody_reminder_kind}'='supplier','saved label missing';
 assert (saved#>>'{account,lines,0,subtotal}')::numeric=100,'tag changed money';
 assert public.save_baihuayuan_receipt_review(a,batch,input,req)=saved,'receipt retry';
 assert (select remaining from private.custody_reminders where id=reminder)=98,'retry deducted twice';
 r:=saved->'account';input:=input||jsonb_build_object('source_fingerprint',r->>'source_fingerprint','revision',r->'revision','lines',jsonb_build_array((r->'lines'->0)||jsonb_build_object('quantity',3,'subtotal',150)));
 saved:=public.save_baihuayuan_receipt_review(a,batch,input,gen_random_uuid());
 assert (select remaining from private.custody_reminders where id=reminder)=97,'edit must subtract delta only';
 r:=saved->'account';input:=input||jsonb_build_object('source_fingerprint',r->>'source_fingerprint','revision',r->'revision','lines',jsonb_build_array((r->'lines'->0)||jsonb_build_object('quantity',101)));
 begin perform public.save_baihuayuan_receipt_review(a,batch,input,gen_random_uuid());raise exception 'overdraw accepted';exception when sqlstate '22023' then assert sqlerrm='REMINDER_INSUFFICIENT';end;
 assert (select remaining from private.custody_reminders where id=reminder)=97,'failure rollback';
 input:=input||jsonb_build_object('lines',jsonb_build_array((r->'lines'->0)||jsonb_build_object('custody_reminder_id',reserved,'quantity',3)));
 saved:=public.save_baihuayuan_receipt_review(a,batch,input,gen_random_uuid());
 assert (select remaining from private.custody_reminders where id=reminder)=100,'relink restore';
 assert (select remaining from private.custody_reminders where id=reserved)=17,'reserved deduction';
 perform public.set_baihuayuan_record_state(a,'RECEIPT_BATCH',batch,'REMOVED','回滾測試');
 assert (select remaining from private.custody_reminders where id=reserved)=20,'remove restores';
 perform public.set_baihuayuan_record_state(a,'RECEIPT_BATCH',batch,'LIVE',null);
 assert (select remaining from private.custody_reminders where id=reserved)=17,'restore deducts once';
 r:=public.get_baihuayuan_receipt_accounts(a,null,null,null,batch)->0;
 input:=input||jsonb_build_object('source_fingerprint',r->>'source_fingerprint','revision',r->'revision','lines',jsonb_build_array((r->'lines'->0)||jsonb_build_object('custody_reminder_id','')));
 saved:=public.save_baihuayuan_receipt_review(a,batch,input,gen_random_uuid());
 assert (select remaining from private.custody_reminders where id=reserved)=20,'ordinary purchase restores remainder';
 assert not exists(select 1 from private.custody_reminder_receipts where batch_id=batch),'unlink missing';
 assert (select to_jsonb(g) from public.goods_receipts g where id=receipt)=raw_goods,'source receipt changed';
 assert (select jsonb_agg(to_jsonb(f) order by f.id) from public.receipt_ocr_fields f where batch_id=batch)=raw_fields,'OCR evidence changed';
 assert (select jsonb_agg(to_jsonb(m) order by m.store_id,m.user_id) from public.store_memberships m where organization_id=org)=raw_members,'roles changed';
 assert (select count(*) from private.staff_pin_credentials)=pin_count,'PIN records changed';
 assert (select coalesce(jsonb_agg(to_jsonb(p)),'[]') from private.stock_positions p where store_id=a)=before_positions,'reminder adds duplicate physical stock';

 -- Extended safety stock and replenishment lifecycle, only on isolated fixture records.
 state:=public.baihuayuan_custody_reminders(a);
 input:=(select x from jsonb_array_elements(state->'rows') x where x->>'id'=reminder::text)||jsonb_build_object('remaining',55,'safety_stock',60,'responsible_user_id',admin_id);
 req:=gen_random_uuid();state:=public.baihuayuan_custody_reminders(a,'save',input,req);
 assert public.baihuayuan_custody_reminders(a,'save',input,req)=state,'threshold retry';
 assert (select remaining=55 and safety_stock=60 from private.custody_reminders where id=reminder),'metadata changed balance';
 assert (select private.custody_replenishment_status(x)='LOW' from private.custody_reminders x where id=reminder),'low stock state';
 assert (select count(*)=1 from private.custody_daily_notifications where reminder_id=reminder),'low notification absent';
 perform private.enqueue_custody_notifications(reminder);perform private.enqueue_custody_notifications(reminder);
 assert (select count(*)=1 from private.custody_daily_notifications where reminder_id=reminder),'daily duplicate';
 assert not has_function_privilege('authenticated','private.enqueue_custody_notifications(uuid)','execute'),'global cron access';
 assert not has_table_privilege('authenticated','private.custody_replenishments','select,insert,update,delete'),'order direct access';
 assert not has_table_privilege('anon','private.custody_daily_notifications','select'),'notification leak';
 perform set_config('request.jwt.claim.sub',staff_id::text,true);
 state:=public.baihuayuan_custody_reminders(a);
 assert state->>'can_edit'='false','staff edit access';
 assert jsonb_array_length(state->'recipients')=0,'staff recipient leak';
 assert (select x->>'notified_at' is null from jsonb_array_elements(state->'rows') x where x->>'id'=reminder::text),'staff notification leak';
 begin perform public.baihuayuan_custody_reminders(a,'order',input,gen_random_uuid());raise exception 'staff order accepted';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 state:=public.baihuayuan_custody_reminders(a);
 assert (select x->>'notified_at' is not null from jsonb_array_elements(state->'rows') x where x->>'id'=reminder::text),'recipient notification absent';
 perform set_config('request.jwt.claim.sub',owner_id::text,true);
 -- Existing receipt pathway still applies delta-only and does not touch physical inventory.
 r:=public.get_baihuayuan_receipt_accounts(a,null,null,null,batch)->0;
 input:=jsonb_build_object('source_fingerprint',r->>'source_fingerprint','revision',r->'revision','header',jsonb_build_object('supplier_name',r->>'supplier_name','receipt_date','2026-09-15','document_number','RR-ONLY'),
 'lines',jsonb_build_array((r->'lines'->0)||jsonb_build_object('custody_reminder_id',reminder,'handling','NORMAL','quantity',2,'unit_price',50,'subtotal',100)), 'adjustment',0,'tax',5,'total',105,'note','','checked',false);
 req:=gen_random_uuid();saved:=public.save_baihuayuan_receipt_review(a,batch,input,req);
 assert (select remaining=53 from private.custody_reminders where id=reminder),'55 minus 2';
 perform public.save_baihuayuan_receipt_review(a,batch,input,req);
 assert (select remaining=53 from private.custody_reminders where id=reminder),'55 minus 2 retry';
 state:=public.baihuayuan_custody_reminders(a);
 r:=(select x from jsonb_array_elements(state->'rows') x where x->>'id'=reminder::text);
 input:=jsonb_build_object('id',reminder,'revision',r->'revision','ordered_quantity',100,'expected_on','','note','fixture');
 req:=gen_random_uuid();state:=public.baihuayuan_custody_reminders(a,'order',input,req);
 assert public.baihuayuan_custody_reminders(a,'order',input,req)=state,'order retry';
 assert (select remaining=53 from private.custody_reminders where id=reminder),'placing order increased balance';
 r:=(select x from jsonb_array_elements(state->'rows') x where x->>'id'=reminder::text);
 assert r->>'status'='WAITING_DATE','missing ETA must still remind';
 input:=jsonb_build_object('id',reminder,'revision',r->'revision','order_id',r#>>'{order,id}','order_revision',r#>'{order,revision}','ordered_quantity',100,'expected_on',(now() at time zone 'Asia/Taipei')::date+5,'note','fixture');
 state:=public.baihuayuan_custody_reminders(a,'order',input,gen_random_uuid());
 r:=(select x from jsonb_array_elements(state->'rows') x where x->>'id'=reminder::text);
 assert r->>'status'='ORDERED' and r->>'notified_at' is null,'confirmed ETA should stop alert';
 input:=input||jsonb_build_object('revision',r->'revision','order_revision',r#>'{order,revision}','expected_on',(now() at time zone 'Asia/Taipei')::date-1);
 state:=public.baihuayuan_custody_reminders(a,'order',input,gen_random_uuid());
 r:=(select x from jsonb_array_elements(state->'rows') x where x->>'id'=reminder::text);
 assert r->>'status'='OVERDUE','overdue not tracked';
 input:=jsonb_build_object('id',reminder,'revision',r->'revision','order_id',r#>>'{order,id}','order_revision',r#>'{order,revision}','quantity',2);
 req:=gen_random_uuid();state:=public.baihuayuan_custody_reminders(a,'receive',input,req);
 assert public.baihuayuan_custody_reminders(a,'receive',input,req)=state,'partial receive retry';
 assert (select remaining=55 from private.custody_reminders where id=reminder),'partial receipt balance';
 r:=(select x from jsonb_array_elements(state->'rows') x where x->>'id'=reminder::text);
 assert r#>>'{order,received_quantity}'='2','partial outstanding order lost';
 begin perform public.baihuayuan_custody_reminders(a,'receive',input,gen_random_uuid());raise exception 'stale receive accepted';exception when sqlstate 'PT409' then null;end;
 input:=input||jsonb_build_object('revision',r->'revision','order_revision',r#>'{order,revision}','quantity',99);
 begin perform public.baihuayuan_custody_reminders(a,'receive',input,gen_random_uuid());raise exception 'over-receive accepted';exception when sqlstate '22023' then null;end;
 input:=input||jsonb_build_object('quantity',98);req:=gen_random_uuid();state:=public.baihuayuan_custody_reminders(a,'receive',input,req);
 assert public.baihuayuan_custody_reminders(a,'receive',input,req)=state,'final arrival retry';
 r:=(select x from jsonb_array_elements(state->'rows') x where x->>'id'=reminder::text);
 assert r->>'remaining'='153' and r->>'status'='OK' and r->>'order' is null,'complete arrival incorrect';
 assert (select count(*)=1 from private.custody_replenishments where reminder_id=reminder and status='RECEIVED' and received_quantity=100),'order history absent';
 -- Old clients cannot erase safety settings by omitting new fields.
 input:=(r-'safety_stock'-'responsible_user_id');state:=public.baihuayuan_custody_reminders(a,'save',input,gen_random_uuid());
 assert (select safety_stock=60 and responsible_user_id=admin_id from private.custody_reminders where id=reminder),'old client erased settings';
 r:=(select x from jsonb_array_elements(state->'rows') x where x->>'id'=reminder::text);
 state:=public.baihuayuan_custody_reminders(a,'order',jsonb_build_object('id',reminder,'revision',r->'revision','ordered_quantity',10),gen_random_uuid());
 r:=(select x from jsonb_array_elements(state->'rows') x where x->>'id'=reminder::text);
 state:=public.baihuayuan_custody_reminders(a,'cancel_order',jsonb_build_object('id',reminder,'revision',r->'revision','order_id',r#>>'{order,id}','order_revision',r#>'{order,revision}'),gen_random_uuid());
 assert (select remaining=153 from private.custody_reminders where id=reminder),'cancel changed stock';
 assert (select coalesce(jsonb_agg(to_jsonb(p)),'[]') from private.stock_positions p where store_id=a)=before_positions,'supplier arrivals changed physical stock';
end $test$;
rollback;
